#endif
#define ST4EL(p, v, pol) asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;" :: "l"(p), "f"(v[0]),"f"(v[1]),"f"(v[2]),"f"(v[3]), "l"(pol) : "memory")
#if TM==0
#define LDT4(p, v, pt) LD4(p, v)
#else
#define LDT4(p, v, pt) LD4EL(p, v, pt)
#endif
__device__ __forceinline__ unsigned div_magic(unsigned n, unsigned m, unsigned l){ return (__umulhi(n, m) + n) >> l; }

template <int THREADS>
__device__ __forceinline__ void row_impl(const float* __restrict__ q, const float* __restrict__ k,
         const float* __restrict__ cs, const float* __restrict__ sn, float* __restrict__ qo, float* __restrict__ ko,
         unsigned Rq, unsigned R, unsigned S, unsigned m, unsigned l)
{
    constexpr int ROWS = THREADS / 16;
    const unsigned j = threadIdx.x & 15;
    const unsigned r = blockIdx.x * ROWS + (threadIdx.x >> 4);
    if (r >= R) return;
    const float* x; float* y; unsigned rl;
    if (r < Rq) { x = q; y = qo; rl = r; } else { x = k; y = ko; rl = r - Rq; }
    const unsigned s = rl - div_magic(rl, m, l) * S;
    const float* xp = x + (size_t)rl * 128 + j * 4;
    const float* cp = cs + (size_t)s * 128 + j * 4;
    const float* sp = sn + (size_t)s * 128 + j * 4;
    y += (size_t)rl * 128 + j * 4;
    float xl[4], xh[4], cl[4], ch[4], sl[4], sh[4], ol[4], oh[4];
    unsigned long long pf = 0, pt = 0, pol;
    if (XM==2) asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pf));
    if (TM==1) asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pt));
    LDX4(xp, xl, pf); LDX4(xp + 64, xh, pf);
    LDT4(cp, cl, pt);  LDT4(cp + 64, ch, pt);
    LDT4(sp, sl, pt);  LDT4(sp + 64, sh, pt);
    asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
#pragma unroll
    for (int e = 0; e < 4; ++e) { ol[e] = xl[e] * cl[e] - xh[e] * sl[e]; oh[e] = xh[e] * ch[e] + xl[e] * sh[e]; }
    ST4EL(y, ol, pol); ST4EL(y + 64, oh, pol);
}
template <int THREADS>
__device__ __forceinline__ void pair_impl(const float* __restrict__ q, const float* __restrict__ k,
          const float* __restrict__ cs, const float* __restrict__ sn, float* __restrict__ qo, float* __restrict__ ko,
          unsigned Pq, unsigned P, unsigned S, unsigned m, unsigned l)
{
    constexpr int PAIRS = THREADS / 16;
    const unsigned j = threadIdx.x & 15;
    const unsigned p = blockIdx.x * PAIRS + (threadIdx.x >> 4);
    if (p >= P) return;
    const float* x; float* y; unsigned pl;
    if (p < Pq) { x = q; y = qo; pl = p; } else { x = k; y = ko; pl = p - Pq; }
    const unsigned qd = div_magic(pl, m, l);
    const unsigned s = pl - qd * S;
    const size_t row0 = (size_t)(2 * qd) * S + s;
    const size_t hs = (size_t)S * 128;
    const float* xp = x + row0 * 128 + j * 4;
    const float* cp = cs + (size_t)s * 128 + j * 4;
    const float* sp = sn + (size_t)s * 128 + j * 4;
    y += row0 * 128 + j * 4;
    float xl0[4], xh0[4], xl1[4], xh1[4], cl[4], ch[4], sl[4], sh[4], ol[4], oh[4];
    unsigned long long pf = 0, pt = 0, pol;
    if (XM==2) asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pf));
    if (TM==1) asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pt));
    LDX4(xp, xl0, pf);      LDX4(xp + 64, xh0, pf);
    LDX4(xp + hs, xl1, pf); LDX4(xp + hs + 64, xh1, pf);
    LDT4(cp, cl, pt);  LDT4(cp + 64, ch, pt);
    LDT4(sp, sl, pt);  LDT4(sp + 64, sh, pt);
    asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
#pragma unroll
    for (int e = 0; e < 4; ++e) { ol[e] = xl0[e] * cl[e] - xh0[e] * sl[e]; oh[e] = xh0[e] * ch[e] + xl0[e] * sh[e]; }
    ST4EL(y, ol, pol); ST4EL(y + 64, oh, pol);
#pragma unroll
    for (int e = 0; e < 4; ++e) { ol[e] = xl1[e] * cl[e] - xh1[e] * sl[e]; oh[e] = xh1[e] * ch[e] + xl1[e] * sh[e]; }
    ST4EL(y + hs, ol, pol); ST4EL(y + hs + 64, oh, pol);
}
#define ARGS const float* __restrict__ q, const float* __restrict__ k, const float* __restrict__ cs, const float* __restrict__ sn, float* __restrict__ qo, float* __restrict__ ko, unsigned a, unsigned b, unsigned S, unsigned m, unsigned l
extern "C" __global__ void __launch_bounds__(128) row128(ARGS){ row_impl<128>(q,k,cs,sn,qo,ko,a,b,S,m,l); }
extern "C" __global__ void __launch_bounds__(256) row256(ARGS){ row_impl<256>(q,k,cs,sn,qo,ko,a,b,S,m,l); }
extern "C" __global__ void __launch_bounds__(128) pair128(ARGS){ pair_impl<128>(q,k,cs,sn,qo,ko,a,b,S,m,l); }
extern "C" __global__ void __launch_bounds__(256) pair256(ARGS){ pair_impl<256>(q,k,cs,sn,qo,ko,a,b,S,m,l); }
"""
_cub = {}
def kern(xm, tm, name):
    key = (xm, tm, name)
    if key not in _cub:
        src = "#define XM %d\n#define TM %d\n" % (xm, tm) + SRC
        k = cuda_kernel(src, name)
        if name.startswith("pair"):
            attr = driver.CUfunction_attribute.CU_FUNC_ATTRIBUTE_PREFERRED_SHARED_MEMORY_CARVEOUT
            driver.cuFuncSetAttribute(k.fn, attr, 50)
        _cub[key] = k
    return _cub[key]

SHAPES = [(1,8,8,128),(1,40,8,131),(2,32,4,211),(4,24,6,293),(1,56,8,853),(8,16,4,373),(2,48,6,919),(64,8,8,128),
          (8,24,8,1024),(8,28,4,1024),(8,32,4,1087),(4,48,12,1321),(4,36,6,2048),(2,40,8,4096),(1,64,8,8192),(32,16,4,4096)]
def mb(sh):
    B,H,Hk,S = sh; return (2*B*(H+Hk)*S*512 + 2*S*512)/1e6

def magic(S):
    l = 0
    while (1<<l) < S: l += 1
    return ((((1<<32)*((1<<l)-S))//S)+1), l

def make(sh):
    B,H,Hk,S = sh
    d = "cuda"
    q = torch.randn(B,H,S,128,device=d); k = torch.randn(B,Hk,S,128,device=d)
    c = torch.cos(torch.randn(S,128,device=d).clamp(-2,2)); s = torch.sin(torch.randn(S,128,device=d).clamp(-2,2))
    return q,k,c,s,torch.empty_like(q),torch.empty_like(k)

def ref(q,k,c,s):
    def rot(x): return torch.cat((-x[...,64:], x[...,:64]),-1)
    return q*c+rot(q)*s, k*c+rot(k)*s

def launcher(sh, cfg):
    """cfg = (path, threads, xm, tm)"""
    B,H,Hk,S = sh
    Rq = B*H*S; R = Rq + B*Hk*S
    path, thr, xm, tm = cfg
    m, l = magic(S)
    kk = kern(xm, tm, path+str(thr))
    if path == "row":
        grid = (R + thr//16 - 1)//(thr//16); a, b = Rq, R; smem = 0
    else:
        P = R//2; grid = (P + thr//16 - 1)//(thr//16); a, b = Rq//2, P
        smem = 11500 if thr == 128 else 24000
    def f(q,k,c,s,qo,ko):
        kk((grid,), (thr,), q,k,c,s,qo,ko, a, b, S, m, l, smem=smem)
    return f

def bench(shapes_cfgs, repeats=3, check=False):
    """shapes_cfgs: list of (shape, {name: cfg}); prints per-variant medians + spread"""
    for sh, cfgs in shapes_cfgs:
        t0 = time.time()
        args = make(sh)
        res = {n: [] for n in cfgs}
        if check:
            rq, rk = ref(*args[:4])
        for rep in range(repeats):
            for n, cfg in cfgs.items():
                f = launcher(sh, cfg)
                res[n].append(harness_time(f, args[:4], args[4:]))
        out = []
        base = None
        for n, v in res.items():
            med = statistics.median(v)
            if base is None: base = med
            out.append("%s %.2f[%.2f-%.2f] %+.1f%%" % (n, med, min(v), max(v), (med/base-1)*100))
        s = "%s %.0fMB | " % (str(sh), mb(sh)) + " | ".join(out)
        if check:
            e1 = (args[4]-rq).abs().max().item(); e2 = (args[5]-rk).abs().max().item()
            s += " | err %.1e %.1e" % (e1, e2)
        print(s, "(%.0fs)" % (time.time()-t0), flush=True)
'''
