for cfg in [("row",128,0,0),("pair",128,0,0),("pair",256,2,1),("row",256,1,1),("pair",128,2,0)]:
    L.launcher(sh,cfg)(*a)
    print(cfg, (a[4]-rq).abs().max().item(), (a[5]-rk).abs().max().item())
print(L.mb(sh))

