                            unsigned H, unsigned Hkv, cudaStream_t stream)
{
    // magic divisor for S: l = ceil(log2 S), m = floor(2^32 (2^l - S) / S) + 1
    unsigned l = 0;
    while ((1ull << l) < S) ++l;
    const unsigned m = (unsigned)((((1ull << 32) * ((1ull << l) - S)) / S) + 1);
    if (H % 2 == 0 && Hkv % 2 == 0 && R > 4096u && S <= 2048u) {
        // 6.6-354 MB workloads: two heads per 16 lanes, 8 pairs per 128-thread CTA, 10 CTAs/SM
        static bool attr_set = false;            // kernel attribute, independent of the call's data
        if (!attr_set) {
            cudaFuncSetAttribute(rope_pair<128, false>, cudaFuncAttributePreferredSharedMemoryCarveout, PAIR_CARVEOUT_PCT);
            cudaFuncSetAttribute(rope_pair<128, true>, cudaFuncAttributePreferredSharedMemoryCarveout, PAIR_CARVEOUT_PCT);
            attr_set = true;
        }
        const unsigned P = R / 2;
        const unsigned grid = (P + 7) / 8;
        if (R >= 120000u && S <= 256u)           // 134 MB: 128 KB tables sit in L1, plain x loads win by 1.5%
            rope_pair<128, true><<<grid, 128, PAIR_PAD_SMEM, stream>>>(q, k, cs, sn, qo, ko, Rq / 2, P, S, m, l);
        else
            rope_pair<128, false><<<grid, 128, PAIR_PAD_SMEM, stream>>>(q, k, cs, sn, qo, ko, Rq / 2, P, S, m, l);
    } else if (R <= 262144u) {     // 8 rows per 128-thread CTA
        const unsigned grid = (R + 7) / 8;
        rope_row<128, false, false><<<grid, 128, 0, stream>>>(q, k, cs, sn, qo, ko, Rq, R, S, m, l);
    } else if (R > 450000u) {      // 612 and 2689 MB: tables (8-16 MB) kept in L2 with evict_last
        const unsigned grid = (R + 15) / 16;
        rope_row<256, false, true><<<grid, 256, 0, stream>>>(q, k, cs, sn, qo, ko, Rq, R, S, m, l);
    } else {                       // 16 rows per 256-thread CTA
        const unsigned grid = (R + 15) / 16;
        rope_row<256, false, false><<<grid, 256, 0, stream>>>(q, k, cs, sn, qo, ko, Rq, R, S, m, l);
