            rope_pair<128, true><<<grid, 128, PAIR_PAD_SMEM, stream>>>(q, k, cs, sn, qo, ko, Rq / 2, P, S, m, l);
        else
            rope_pair<128, false><<<grid, 128, PAIR_PAD_SMEM, stream>>>(q, k, cs, sn, qo, ko, Rq / 2, P, S, m, l);
